"""Ciencias Naturales EPJA Básica N2, módulo 1, desempeño OAD-01: describir a partir de la observación los niveles de organización de los seres vivos (célula, tejido, órgano, sistema, organismo). Todo en papel; datos de ejemplo."""
from __future__ import annotations

from hc_common import make_build

MATERIALS = "Papel, lápiz y goma. Todo se resuelve con las observaciones de ejemplo escritas en la ficha: no se hace ningún experimento real ni se usa microscopio. Si quieres mirar una hoja o una fruta de tu casa, solo obsérvala y no la pruebes ni la cortes con elementos peligrosos."
build = make_build(MATERIALS)

O1 = "EPJA-CNAT-NB2-OAD-01"
PRIOR = ["Ya sé que los seres vivos nacen, crecen y se alimentan.", "He visto plantas, animales y personas, y puedo describir cómo son."]


def K(n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_):
    build(O1, n, F, use=use, prior=PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes, T=T, ctx=ctx, sc=sc, op=op, reinforce=rf, extend=ex_)


